import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updatePaymentSessionClientDataWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updatePaymentSessionClientDataWorkflow(req.scope)
    .run({
      input: {
        payment_collection_id: "paycol_123",
        payment_session_id: "payses_123",
        client_data: {
          payment_method: "pm_123"
        }
      }
    })

  res.send(result)
}

